import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE n (i INTEGER); INSERT INTO n VALUES (1), (2), (3), (4)');
  const stmt = db.prepare('SELECT i FROM n WHERE i > ? ORDER BY i');
  console.log(stmt.get(10) === undefined, stmt.all(2).length);
  const seen: number[] = [];
  for (const row of stmt.iterate(0) as any) { seen.push(row.i); if (seen.length === 2) break; }
  console.log(seen.join(','));
  const it: any = stmt.iterate(3);
  console.log(JSON.stringify(it.next()), JSON.stringify(it.next()), JSON.stringify(it.return()));
  db.close();
}
